package dev.veltraph.client.inventory.bottle;

import dev.veltraph.client.game.GameArea;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.inventory.bottle.BottleAcquisitionRuntime.*;
import static dev.veltraph.client.inventory.bottle.BottleAcquisitionLandingSupportTest.copy;

class BottleAcquisitionTravelClockTest {
    private static Travel cloneTicket(Travel t){return new Travel(t.sequence(),t.player(),t.world(),t.connection(),t.uuid(),t.landing(),t.serial(),t.issuedMillis(),t.expiresMillis(),t.inventory());}
    @Test void clockOnlyWaitReadsNoPortAndDispatchesNoActionOrContextAdoption(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();var originPlayer=t.player();var originWorld=t.world();int reads=r.port.readCalls;r.port.menu=new Object();r.port.connection=new Object();r.port.inventory.clear();for(int i=1;i<=5;i++)assertEquals(Progress.WAITING,r.runtime.waitIssuedTravel(t,r.tick+i,t.issuedMillis()+i*50));assertSame(t,r.runtime.pendingTravel().orElseThrow());assertSame(originPlayer,t.player());assertSame(originWorld,t.world());assertEquals(reads,r.port.readCalls);assertEquals(1,r.port.commands);assertEquals(0,r.port.walks);assertEquals(0,r.port.interactions);assertEquals(0,r.port.purchases);assertEquals(0,r.port.fills);assertEquals(0,r.port.closes);}
    @Test void repeatedLoadingWaitCannotRenewOriginalActionDeadline(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();assertEquals(Progress.WAITING,r.runtime.waitIssuedTravel(t,r.tick+30,t.expiresMillis()));assertEquals(Progress.FAILED,r.runtime.waitIssuedTravel(t,r.tick+31,t.expiresMillis()));assertEquals(State.FAILED,r.runtime.state());assertTrue(r.runtime.pendingTravel().isEmpty());assertEquals(1,r.port.commands);}
    @Test void originalWallDeadlineExpiresDespiteShortLogicalWait(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();assertEquals(Progress.FAILED,r.runtime.waitIssuedTravel(t,r.tick+1,t.expiresMillis()+1));assertEquals(0,r.port.interactions);}
    @Test void reversedLogicalAndWallClocksReject(){for(boolean logical:new boolean[]{true,false}){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();assertEquals(Progress.WAITING,r.runtime.waitIssuedTravel(t,r.tick+2,t.issuedMillis()+100));assertEquals(Progress.FAILED,r.runtime.waitIssuedTravel(t,logical?r.tick+1:r.tick+3,logical?t.issuedMillis()+150:t.issuedMillis()+50));}}
    @Test void equalValuedClonedTicketDoesNotAuthorizeLoadingWait(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();assertEquals(t,cloneTicket(t));assertEquals(Progress.FAILED,r.runtime.waitIssuedTravel(cloneTicket(t),r.tick+1,t.issuedMillis()+50));assertEquals(State.FAILED,r.runtime.state());}
    @Test void cancelledTicketCannotWakeOrRestartParent(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();r.runtime.cancel();assertEquals(Progress.FAILED,r.runtime.waitIssuedTravel(t,r.tick+1,t.issuedMillis()+50));assertEquals(State.CANCELLED,r.runtime.state());assertEquals(1,r.port.commands);}
    @Test void readOnlyAdmissionChangesNeitherTicketClocksNorActionCounts(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();var o=r.port.read();assertEquals(Admission.WAIT,r.runtime.inspectTravel(t,copy(o,false,GameArea.HUB),r.tick+10));assertEquals(Admission.WAIT,r.runtime.inspectTravel(t,copy(o,true,GameArea.UNKNOWN),r.tick+11));assertEquals(Admission.READY,r.runtime.inspectTravel(t,o,r.tick+1));assertEquals(State.WAIT_TRAVEL,r.runtime.state());assertSame(t,r.runtime.pendingTravel().orElseThrow());assertEquals(1,r.port.commands);assertEquals(0,r.port.walks);assertEquals(0,r.port.interactions);}
    @Test void settlingNeverForgivesWrongFreshPacketPositionInventorySelectionContextOrArea(){for(int variant=0;variant<7;variant++){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();if(variant==0)r.port.teleport=new Vec3(100,70,0);if(variant==1)r.port.pos=new Vec3(100,70,0);if(variant==2)r.port.inventory.set(2,BottleFillWorkflow.Stack.EMPTY);if(variant==3)r.port.selected=3;if(variant==4)r.port.connection=new Object();if(variant==5)r.port.uuid=UUID.randomUUID();if(variant==6)r.port.area=GameArea.THE_END;var o=copy(r.port.read(),false,r.port.area);assertEquals(Admission.STOP,r.runtime.inspectTravel(t,o,r.tick+1),"variant"+variant);assertEquals(State.WAIT_TRAVEL,r.runtime.state(),"peek is read-only");assertEquals(Progress.FAILED,r.runtime.pollTravel(o,r.tick+1));assertEquals(0,r.port.walks);assertEquals(0,r.port.interactions);}}
    @Test void protectedInventoryDriftRejectsEvenBeforeFreshPacket(){var r=new BottleAcquisitionRuntimeTest.Run();r.port.withholdTravel=true;r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();r.port.inventory.set(2,BottleFillWorkflow.Stack.EMPTY);assertEquals(Admission.STOP,r.runtime.inspectTravel(t,r.port.read(),r.tick+1));}
    @Test void ordinaryForeignMenuCannotUseClockOnlyAdmission(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();r.port.open("Private Quotes");assertEquals(Admission.STOP,r.runtime.inspectTravel(t,r.port.read(),r.tick+1));assertEquals(Progress.FAILED,r.runtime.pollTravel(r.port.read(),r.tick+1));}
    @Test void supportedReceiptAfterOriginalDeadlineCannotCommit(){var r=new BottleAcquisitionRuntimeTest.Run();r.reach(State.WAIT_TRAVEL);var t=r.runtime.pendingTravel().orElseThrow();var o=copy(r.port.read(),false,GameArea.HUB);assertEquals(Progress.WAITING,r.runtime.pollTravel(o,r.tick+30));assertEquals(Admission.STOP,r.runtime.inspectTravel(t,copy(o,true,GameArea.HUB),r.tick+31));assertEquals(Progress.FAILED,r.runtime.pollTravel(copy(o,true,GameArea.HUB),r.tick+31));assertEquals(0,r.port.interactions);}
    @Test void cumulativeDeadlineStillWinsOverLaterOperationDeadline(){var p=BottleAcquisitionRuntimeTest.profile(1,1000);var limited=new Profile(p.glass(),p.hub(),p.island(),p.path(),p.npcAnchor(),p.npcStand(),p.npcName(),p.npcType(),p.npcTitle(),p.option(),p.buyTitle(),p.offer(),p.reserveThreshold(),p.cycles(),p.maxStackCost(),p.maxTotalCost(),p.delayTicks(),p.timeoutTicks(),p.timeoutTicks());var port=new BottleAcquisitionRuntimeTest.Fake();var rt=new BottleAcquisitionRuntime(port);assertTrue(rt.start(limited,0));port.now=50;rt.tick(1);var t=rt.pendingTravel().orElseThrow();assertEquals(Progress.WAITING,rt.waitIssuedTravel(t,30,1500));assertEquals(Progress.FAILED,rt.waitIssuedTravel(t,31,1501));assertEquals(1,port.commands);}
}
